dir:




















































  &DefaultButton;




function filter$hrdkcanvMulti(p){
  this.constructor(p);
}
filter$hrdkcanvMulti.prototype = new DirEvent();
filter$hrdkcanvMulti.prototype.afterInit = function(){
  var p = this._dir;
}
filter$hrdkcanvMulti.prototype.beforeButtonDialogClick = function (id) {
  var p = this._dir;
  switch (id) {
    case 'filterOk':
      if (p.valForm('ma_nv').trim() + p.valForm('ma_bp').trim() == '') {
         $.showToast(p.msg('NotEnoughInfoEmp'));
         p.jObject('ma_bp').focus();
				 return false;
			}
      if (p.valForm('ma_ca').trim() + p.valForm('nh_ca').trim() == '') {
         $.showToast(p.msg('NotEnoughInfoCa'));
         p.jObject('ma_ca').focus();
				 return false;
			}
      break;
    default:
      break;
  }
  return true;
}
filter$hrdkcanvMulti.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
  switch (cF){
    case 'ma_nv':
      if (p.valForm('ma_nv') !='') {p.valForm('ma_bp', '')}
      break;
		case 'ma_bp':
      if (p.valForm('ma_bp') !='') {p.valForm('ma_nv', '')}
      break;
		case 'ma_ca':
			if (p.valForm('ma_ca') !='') p.valForm(['nh_ca', 'ten_nh_ca'], ['', '']);
			break;
		case 'nh_ca':
			if (p.valForm('nh_ca') !='') p.valForm(['ma_ca', 'ten_ca'], ['', '']);
			break;
    default:
      break;
  }
}








exec iswiftStoredMultiRegiterShift @ngay_tu, @ngay_den, @ma_bp, @ma_nv, @ma_ca, @nh_ca, @xu_ly, @@userId
select '' as message, '$Processed' as toast, 'p.options.parent._refresh(true); p._close();' as script
